models = {
    "small-1B": {"layers": 16, "heads": 16, "head_dim": 64},
    "mid-8B": {"layers": 32, "heads": 32, "head_dim": 128},
}
bytes_fp16 = 2

table = []
for name, m in models.items():
    per_token = 2 * m["layers"] * m["heads"] * m["head_dim"] * bytes_fp16   # K and V
    for seq_len in [4_096, 128_000]:
        gb = round(per_token * seq_len / 1e9, 2)
        table.append((name, seq_len, per_token, gb))

for name, seq_len, per_token, gb in table:
    print(f"{name:9} {seq_len:>7} tokens: {per_token:>7} B/token -> {gb} GB")
